CREATE OR REPLACE VIEW `vwprovvigioni` AS select year(`p`.`data_status`) AS `competenza`,`p`.`denominazione_riferimento` AS `denominazione_riferimento`,sum(`p`.`importo`) AS `Provvigioni`,`p`.`fornitori_id` AS `fornitori_id` from `provvigioni` `p` where ((`p`.`fornitori_id` is not null) and (`p`.`stato` = 'Pagato')) group by year(`p`.`data_status`),`p`.`denominazione_riferimento` order by year(`p`.`data_status`),`p`.`denominazione_riferimento`
